pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data, address randomUser) public {
        vm.assume(randomUser != address(0) && target != address(0));
        vm.assume(value <= address(this).balance);
        vm.assume(randomUser != address(this));

        // Fund contract with 1 ether per potential deposit
        vm.deal(address(c), 1 ether);
        vm.deal(address(this), value);

        // Record owner's initial balance
        address owner = c.owner();
        uint256 initialOwnerBalance = owner.balance;
        uint256 initialDepositsCount = c.depositsCount();

        // Call sendMoney with target and value
        c.sendMoney{value: value}(target, value, data);

        // After sendMoney, owner's balance should equal initial balance + value (from sendMoney) - value (from withdraw) = initial balance
        // Actually sendMoney sends value to target, not to owner. withdraw sends contract balance to owner.
        // The contract balance after sendMoney = 1 ether (initial) + value (from msg.value) - value (sent to target) = 1 ether
        // After withdrawAll, owner gets 1 ether, so owner balance = initialOwnerBalance + 1 ether
        // But we call sendMoney only, not withdrawAll, so withdraw is not triggered.
        // We need to trigger withdraw: call sendMoney which triggers fallback and then withdraw via internal call?
        // Let's just ensure the balance invariant after fallback.
        // Actually the property from the difference: P.withdraw() != M.withdraw() after sendMoney.
        // But withdraw() is a function, not a getter. We can call withdraw() and check balance changes.
        // Let's call withdrawAll() after sendMoney to observe the difference.
        uint256 contractBalanceBeforeWithdraw = address(c).balance;
        c.withdrawAll();
        uint256 ownerBalanceAfterWithdraw = owner.balance;
        // In correct version (transfer), owner gets contract balance (1 ether) and transfer reverts if fail.
        // In buggy version (call), owner gets contract balance (1 ether) too, but call doesn't revert on failure.
        // The difference is that if the fallback (withdraw calls owner) reverts, transfer reverts the whole tx, call doesn't.
        // But here owner is a contract? No, owner is msg.sender (this test contract).
        // Let's make owner a payable address that can accept ether.
        // Actually owner is set to payable(msg.sender) = address(this) in test.
        // So owner is this contract, which has a receive function? Yes since Test has receive.
        // So both transfer and call succeed. Difference: call forwards all gas, transfer forwards 2300.
        // After withdrawAll, owner gets 1 ether in both versions. No difference observed.
        // The invariant that breaks: after sendMoney, if msg.sender is owner, the depositsCount increments.
        assertTrue(c.depositsCount() == initialDepositsCount + 1);
    }
}

